using System;
using System.IO;
using System.Linq;
using System.Text;
using UnityEditor;
using UnityEngine;
using DragLab.Data;
using DragLab.Domain;
using DragLab.Domain.Mechanics;
using DragLab.Infrastructure;
namespace DragLab.Editor {
 public static class IntegratedToolsVerification {
  [MenuItem("DragLab/Verify Integrated Tools and Calibration")]
  public static void RunStandalone(){int count=Run(Path.GetFullPath(Path.Combine(Application.dataPath,"../..")));Debug.Log("2L TOOLS PASS: "+count);}
  public static int Run(string root){
   int count=0;var log=new StringBuilder();Action<bool,string> check=(ok,label)=>{log.AppendLine((ok?"PASS ":"FAIL ")+label);File.WriteAllText(Path.Combine(root,"reports/phases/2l/tools-verification.txt"),log+"Checks: "+count);if(!ok)throw new InvalidOperationException(label);count++;};
   string folder=Path.Combine(root,"reports/phases/2l");Directory.CreateDirectory(folder);var assets=Resources.LoadAll<VehicleDefinition>("Data/Vehicles").OrderBy(v=>v.spec.id).ToArray();var catalog=new MechanicalCatalog(assets.Select(v=>v.spec),false);
   check(DrivingTraceChannels.All.Select(c=>c.label).Distinct().Count()==DrivingTraceChannels.All.Length,"Telemetry labels are unique and CSV-safe.");check(DrivingTraceChannels.Groups.All(g=>DrivingTraceChannels.All.Count(c=>c.group==g)<=12),"Every graph group fits two channel rows.");
   foreach(var part in catalog.parts)check(PartCatalogOverrides.Validate(part,part.Copy())==null,"Authored definition validates: "+part.id+" / "+PartCatalogOverrides.Validate(part,part));
   var candidate=catalog.parts.First(p=>p.category==PartCategory.Cooling);var authoredAsset=assets.First(v=>catalog.Recipe(v.spec.id)[PartCategory.Cooling]==candidate.id);var oldBuild=catalog.Resolve(authoredAsset.spec.id,catalog.Recipe(authoredAsset.spec.id),authoredAsset.CreateStockTune());var draft=candidate.Copy();draft.engineHeatTransferScale*=1.5f;draft.coolingWattsPerC*=1.5f;var bag=new PartCatalogOverrideData();bag.parts.Add(draft);PartCatalogOverrides.Apply(catalog,bag,true);
   check(catalog.Find(draft.id).engineHeatTransferScale==draft.engineHeatTransferScale&&candidate.engineHeatTransferScale!=draft.engineHeatTransferScale,"Validated draft is copied into catalog without mutating original.");
   var changedBuild=catalog.Resolve(authoredAsset.spec.id,catalog.Recipe(authoredAsset.spec.id),authoredAsset.CreateStockTune());var oldCar=new CarSimulation(oldBuild.spec,oldBuild.tune,new DriverSettings());var changedCar=new CarSimulation(changedBuild.spec,changedBuild.tune,new DriverSettings());oldCar.mechanics.Prepare(oldCar.state);changedCar.mechanics.Prepare(changedCar.state);check(changedCar.state.engineCoolingFactor>oldCar.state.engineCoolingFactor*1.4,"Authored cooling transfer changes the actual shared simulation.");
   var frozen=new CarSimulation(JsonUtility.FromJson<VehicleSpec>(JsonUtility.ToJson(oldBuild.spec)),oldBuild.tune,new DriverSettings());frozen.mechanics.Prepare(frozen.state);check(frozen.state.engineCoolingFactor==oldCar.state.engineCoolingFactor,"Captured fitted hardware retains its original definition after project authoring.");
   var before=JsonUtility.ToJson(catalog.Find(draft.id));
   Action<PartCatalogOverrideData,string> rejects=(data,label)=>{bool rejected=false;try{PartCatalogOverrides.Apply(catalog,data,true);}catch(ArgumentException){rejected=true;}check(rejected&&before==JsonUtility.ToJson(catalog.Find(draft.id)),"Atomic authoring rejection: "+label);};
   foreach(string invalid in new[]{"NaN","negative","fitment","category","unknown","range","plates","flags","life"}){var bad=draft.Copy();switch(invalid){case "NaN":bad.massKg=float.NaN;break;case "negative":bad.massKg=-1;break;case "fitment":bad.fitment="wrong";break;case "category":bad.category=PartCategory.Clutch;break;case "unknown":bad.id="unknown";break;case "range":bad.boostMin=bad.boostMax+1;break;case "plates":bad.clutchPlateCount=0;break;case "flags":bad.tuning=(PartTuningOptions)1024;break;case "life":bad.wearEnergyJ=0;break;}rejects(new PartCatalogOverrideData{parts={bad}},invalid);}
   rejects(new PartCatalogOverrideData{parts={draft,draft.Copy()}},"duplicate");rejects(new PartCatalogOverrideData{version=2,parts={draft}},"future schema");
   catalog=new MechanicalCatalog(assets.Select(v=>v.spec));
   var calibration=new StringBuilder("vehicle,configuration,elapsed_s,trap_kmh,points,class,stop_from_35mps_m,stop_seconds\n");
   var runs=new StringBuilder("vehicle,case,ticks,end_speed_kmh,distance_m,fuel_used_l,peak_slip,peak_rpm,body_energy_j,wheel_energy_j,failed\n");
   foreach(var asset in assets){
    var profile=PlayerProfile.New(DateTime.UtcNow.Ticks);profile.cars.Clear();profile.cars.Add(new OwnedCar{vehicleId=asset.spec.id,tune=asset.CreateStockTune()});profile.selectedVehicleId=asset.spec.id;profile.driving=new DriverSettings{launch=LaunchMode.Assisted,shifting=ShiftMode.Sequential,throttleAssist=false,wearMode=WearMode.Full};MechanicsOwnership.Ensure(profile,catalog);
    var capture=PhysicalBenchTransfer.Capture(profile,profile.SelectedCar,20261008);var session=new PhysicalDrivingSession(capture);foreach(var input in PhysicalScenarios.Timeline(PhysicalScenario.FullPullShiftCoastBrake,capture.seed))session.Step(input);
    check(session.samples.All(s=>DrivingTraceChannels.All.All(c=>MechanicsSchema.Finite(c.Value(s)))),"All measured channels finite over staged launch / shifts / lift / braking: "+asset.spec.id);
    check(session.samples.Any(s=>s.wheelDriveNm.Any(n=>Math.Abs(n)>10))&&session.samples.Any(s=>s.wheelBrakeNm.Any(n=>Math.Abs(n)>10)),"Measured wheel drive and actual braking appear independently: "+asset.spec.id);
    check(session.samples.All(s=>s.wheelContactNm.Select((n,i)=>Math.Abs(n-s.wheelForceN[i]*session.car.wheels.radius)<1e-7).All(x=>x)),"Measured reaction torque equals contact force times tire radius: "+asset.spec.id);
    check(session.samples.Where(s=>s.brake==0).All(s=>s.wheelBrakeNm.All(n=>n==0)),"No applied brake torque without pedal/staging brake: "+asset.spec.id);
    check(session.Csv()==PhysicalDrivingSession.Replay(session.snapshot).Csv(),"Full current-model telemetry replay is exact: "+asset.spec.id);
    var continued=session.ContinueRecording();var roundtrip=new PhysicalDrivingSession(JsonUtility.FromJson<RunSnapshot>(JsonUtility.ToJson(continued.snapshot)));for(int tick=0;tick<240;tick++){var input=new TickInput{tick=tick,input=new DriverInput{throttle=.4,shiftUp=tick==0}};continued.Step(input);roundtrip.Step(input);}check(continued.Csv()==roundtrip.Csv(),"Continued JSON trace preserves exact wheel observations and history: "+asset.spec.id);
    var csv=session.Csv().TrimEnd('\n').Split('\n');check(csv.Length==PhysicalScenarios.Ticks+2&&csv.All(row=>row.Split(',').Length==csv[0].Split(',').Length),"CSV retains every 120 Hz row and has matching columns: "+asset.spec.id);File.WriteAllText(Path.Combine(folder,asset.spec.id+"-integrated.csv"),session.Csv());File.WriteAllText(Path.Combine(folder,asset.spec.id+"-capture.json"),JsonUtility.ToJson(session.snapshot,true));
    var resolved=catalog.Resolve(asset.spec.id,catalog.Recipe(asset.spec.id),asset.CreateStockTune());var benchmark=Benchmark.QuarterMile(resolved.spec,resolved.tune);var stop=new CarSimulation(resolved.spec,resolved.tune,new DriverSettings{wearMode=WearMode.Full});RoadFixture.Seed(stop,35,0);double distance=stop.state.distance;int ticks=0;while(stop.state.speed>0&&ticks<6000){stop.IndependentStep(DragMath.FixedStep,new DriverInput{brake=1},true,false);ticks++;}check(stop.state.speed==0&&!stop.state.engineFailed&&!stop.state.brakesFailed,"OEM braking reaches zero without destroying car: "+asset.spec.id);
    calibration.AppendLine(string.Join(",",asset.spec.id,"OEM",F(benchmark.elapsed),F(benchmark.trapKmh),benchmark.points,benchmark.performanceClass,F(stop.state.distance-distance),F(ticks*DragMath.FixedStep)));
    foreach(ShiftMode mode in new[]{ShiftMode.Sequential,ShiftMode.ManualClutch}){var manual=new CarSimulation(resolved.spec,resolved.tune,new DriverSettings{shifting=mode,launch=LaunchMode.Automatic,throttleAssist=false,wearMode=WearMode.Full});var race=new RaceSimulation(manual,new CarSimulation(resolved.spec,resolved.tune,new DriverSettings()),402.336);int ticksRace=0;while(race.phase!=RacePhase.Finished&&ticksRace++<12000){bool shift=manual.state.gear>0&&manual.state.gear<manual.spec.gears.Length&&manual.state.shiftRemaining==0&&manual.state.speed>1&&manual.state.clutch<.2&&manual.state.clutchSlipRpm<250&&manual.state.rpm>=Math.Min(manual.tune.shiftRpm,manual.ShiftPoint(manual.state.gear));race.Step(new DriverInput{throttle=manual.state.launched?1:0,clutch=mode==ShiftMode.ManualClutch&&shift?1:0,shiftUp=shift});}check(manual.state.finished&&!manual.state.engineFailed&&Math.Abs(manual.state.elapsed-benchmark.elapsed)<benchmark.elapsed*.25,"Matched OEM driver mode finishes within 25% of assisted calibration: "+asset.spec.id+" / "+mode+" / "+manual.state.elapsed);calibration.AppendLine(string.Join(",",asset.spec.id,mode,F(manual.state.elapsed),F(manual.state.trapSpeed),benchmark.points,benchmark.performanceClass,"",""));}
    foreach(string scenario in new[]{"stock","payload250","fuel5","radius130","pressure18","cold","reduced","none"}){var start=PhysicalDrivingSession.Copy(capture);if(scenario=="payload250")start.tune.payloadMassKg=250;if(scenario=="fuel5")start.startingFuel.litres=Math.Min(5,start.vehicle.fuel.capacityLitres);if(scenario=="radius130")start.tune.wheelDiameter=1.3f;if(scenario=="pressure18")start.tune.tirePressurePsi=18;if(scenario=="cold")start.tune.coldStart=true;if(scenario=="reduced"){start.driving.wearMode=WearMode.Partial;start.driving.fuelUsage=FuelUsageMode.Reduced;}if(scenario=="none"){start.driving.wearMode=WearMode.None;start.driving.fuelUsage=FuelUsageMode.None;}var run=new PhysicalDrivingSession(start);foreach(var input in PhysicalScenarios.Timeline(PhysicalScenario.FullPullShiftCoastBrake,start.seed))run.Step(input);check(run.car.state.contact.Validate()==null&&run.samples.All(s=>DrivingTraceChannels.All.All(c=>MechanicsSchema.Finite(c.Value(s)))),"Controlled integrated scenario remains finite: "+asset.spec.id+" / "+scenario);if(scenario=="none")check(run.car.mechanics.parts.All(p=>p.condition.health==1&&!p.condition.failed)&&run.samples.Last().fuelUsedLitres==start.startingFuel.cumulativeUsedLitres,"None wear/fuel remains respected in integrated scenario: "+asset.spec.id);var last=run.samples.Last();runs.AppendLine(string.Join(",",asset.spec.id,scenario,run.Tick,F(last.speedKmh),F(last.distance),F(last.fuelUsedLitres),F(run.samples.Max(s=>s.slipEstimate)),F(run.samples.Max(s=>s.rpm)),F(last.bodyEnergyJ),F(last.wheelEnergyJ),last.failed));File.WriteAllText(Path.Combine(folder,asset.spec.id+"-"+scenario+".json"),JsonUtility.ToJson(run.snapshot,true));}
   }
   File.WriteAllText(Path.Combine(folder,"calibration.csv"),calibration.ToString());File.WriteAllText(Path.Combine(folder,"controlled-runs.csv"),runs.ToString());File.WriteAllText(Path.Combine(folder,"tools-verification.txt"),"Model: "+MechanicsSchema.Model+"\n"+log+"Checks: "+count+"\n");return count;
  }
  static string F(double value){return value.ToString("R",System.Globalization.CultureInfo.InvariantCulture);}
 }
}
